#!/usr/bin/env bash
# Generate .claude/AGENTS.md from the actual frontmatter of every agent, command, and skill.
# Single source of truth — hand-maintained roster tables drift, generated ones cannot.
#   roster.sh          — regenerate
#   roster.sh --check  — exit 1 if the file is stale (CI / pre-commit friendly)

source "$(dirname "${BASH_SOURCE[0]}")/lib.sh"
OUT="$ROOT/.claude/AGENTS.md"

gen() {
  cat <<'HDR'
<!-- GENERATED by .claude/scripts/roster.sh — do not edit by hand. -->
<!-- Regenerate after adding or renaming any agent, command, or skill. -->

# Studio AI Toolkit — Roster

Everything below lives at the **workspace root** (`./.claude/`) and is therefore available
from every project, every repo, and every worktree. Run Claude from the workspace root.

Agents, commands, and skills here are **project-agnostic**: they resolve what to act on
through `.claude/scripts/_project.py` and each project's `projects/<name>/project.json`.
Project-specific conventions live in `projects/<name>/AGENTS.md` and that project's own skills, never here.

HDR
  printf '_Generated %s_\n\n' "$(date '+%Y-%m-%d %H:%M')"

  echo "## Agents ($(ls "$ROOT/.claude/agents"/*.md 2>/dev/null | wc -l | tr -d ' '))"
  echo
  echo "| Agent | Tier | Role |"
  echo "|---|---|---|"
  for f in "$ROOT/.claude/agents"/*.md; do
    printf '| `%s` | %s/%s | %s |\n' "$(basename "$f" .md)" \
      "$(sed -n 's/^model: *//p' "$f" | head -1)" "$(sed -n 's/^effort: *//p' "$f" | head -1)" \
      "$(sed -n 's/^description: *//p' "$f" | head -1 | sed 's/|/\\|/g')"
  done

  echo
  echo "## Slash commands ($(ls "$ROOT/.claude/commands"/*.md 2>/dev/null | wc -l | tr -d ' '))"
  echo
  echo "| Command | Purpose |"
  echo "|---|---|"
  for f in "$ROOT/.claude/commands"/*.md; do
    printf '| `/%s` | %s |\n' "$(basename "$f" .md)" \
      "$(sed -n 's/^description: *//p' "$f" | head -1 | sed 's/|/\\|/g')"
  done

  echo
  echo "## Skills ($(ls -d "$ROOT/.claude/skills"/*/ 2>/dev/null | wc -l | tr -d ' '))"
  echo
  echo "| Skill | Loads for |"
  echo "|---|---|"
  for d in "$ROOT/.claude/skills"/*/; do
    local f="$d/SKILL.md"; [[ -f "$f" ]] || continue
    printf '| `%s` | %s |\n' "$(basename "$d")" \
      "$(sed -n 's/^description: *//p' "$f" | head -1 | sed 's/|/\\|/g')"
  done

  echo
  echo "## Scripts"
  echo
  echo "| Script | Purpose |"
  echo "|---|---|"
  for f in "$ROOT/.claude/scripts"/*.sh; do
    [[ "$(basename "$f")" == "lib.sh" ]] && continue
    printf '| `.claude/scripts/%s` | %s |\n' "$(basename "$f")" \
      "$(sed -n '2,4s/^# //p' "$f" | head -1)"
  done
}

if [[ "${1:-}" == "--check" ]]; then
  tmp="$(mktemp)"; gen | grep -v '^_Generated' > "$tmp"
  if diff -q <(grep -v '^_Generated' "$OUT" 2>/dev/null) "$tmp" >/dev/null 2>&1; then
    ok "roster up to date"; rm -f "$tmp"
  else
    warn "AGENTS.md is stale — run: bash .claude/scripts/roster.sh"; rm -f "$tmp"; exit 1
  fi
else
  gen > "$OUT"
  ok "wrote $OUT ($(wc -l < "$OUT" | tr -d ' ') lines)"
fi
